export function resolveName(name, nodes, aliases = {}) {
  const seen = new Set();
  let target = name;

  while (true) {
    const hasAlias = Object.prototype.hasOwnProperty.call(aliases, target);
    const alias = hasAlias ? aliases[target] : undefined;
    if (alias != null) {
      if (seen.has(target)) throw new Error('Alias cycle: ' + target);
      seen.add(target);
      target = alias;
      continue;
    }

    if (Object.prototype.hasOwnProperty.call(nodes, target)) return target;
    throw new Error('Unknown node: ' + target);
  }
}
